#include <iostream>
#include <algorithm>
using namespace std;

long long compute(long long n) {
    if (n == 0) return 0;
    long long base = 1, count = 1;
    while (base <= n) {
        base = base * 10 + 1;
        count++;
    }
    count--;
    base = (base - 1) / 10;
    if (base == n) return count;
    long long result = (1LL << 60);
    if ((base * 10 + 1 - n) < n) {
        result = compute(base * 10 + 1 - n) + count + 1;
    }
    long long max_multiple = 1;
    long long temp;
    while (base * max_multiple <= n) {
        temp = base * max_multiple;
        max_multiple++;
    }
    max_multiple--;
    long long option2 = compute(n - temp) + count * (max_multiple - 1);
    return min(result, option2);
}

int main() {
    ios::sync_with_stdio(false);
    long long number;
    cin >> number;
    cout << compute(number);
    return 0;
}
